use kimo_core::{color::{encode_contract,pipeline},commands::{Session,dispatch}};use serde_json::json;use std::process::Command;
#[test]fn exact_domains_fail_closed(){let mut q=pipeline::Pipeline::default();let c=encode_contract::high(&q,"hevc10").unwrap();assert_eq!((c.primaries,c.transfer_tag,c.matrix,c.range),("bt709","iec61966-2-1","bt709","tv"));q.enabled=true;for g in 0..8{for t in 0..9{q.output_gamut=g;q.output_transfer=t;let expected=g<=1&&([0,1,8].contains(&t)||g==1&&[6,7].contains(&t));assert_eq!(encode_contract::high(&q,"hevc10").is_ok(),expected);}}}
#[test]fn disabled_highbit_tags_and_precision(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":1024,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"gradient","color":[0.,0.,0.],"color2":[1.,1.,1.],"start":0,"duration":0.08})).unwrap();for format in ["hevc10","ffv1_16"]{let path=format!("/tmp/encode-contract-{}-{}.{}",std::process::id(),format,if format=="hevc10"{"mp4"}else{"mkv"});pipeline::export_high(&s.project,&path,format,0).unwrap();let probe=Command::new("ffprobe").args(["-v","error","-show_entries","stream=pix_fmt,color_range,color_space,color_transfer,color_primaries","-of","json",&path]).output().unwrap();let v:serde_json::Value=serde_json::from_slice(&probe.stdout).unwrap();let st=&v["streams"][0];assert_eq!(st["color_primaries"],"bt709");assert_eq!(st["color_transfer"],"iec61966-2-1");assert_eq!(st["color_range"],if format=="hevc10"{"tv"}else{"pc"});assert_eq!(st["color_space"],if format=="hevc10"{"bt709"}else{"gbr"});
let decode=||Command::new("ffmpeg").args(["-v","error","-i",&path,"-frames:v","1","-f","rawvideo","-pix_fmt",if format=="hevc10"{"yuv420p10le"}else{"gbrp16le"},"-"]).output().unwrap().stdout;
let before=decode();let words:Vec<u16>=before.chunks_exact(2).map(|v|u16::from_le_bytes([v[0],v[1]])).collect();let ramp:Vec<u16>=(0..1024).map(|y|words[y*32+16]).collect();assert!(ramp.iter().copied().collect::<std::collections::HashSet<_>>().len()>256,"not an 8-bit quantized pipe");
for (y,actual) in ramp.iter().enumerate(){let f=y as f32/1024.;let packed=(f*65535.+0.5) as u16;if format=="ffv1_16"{assert_eq!(*actual,packed,"exact 16-bit sample {y}");}else{let expected=(64.+876.*packed as f64/65535.).round() as i32;assert!((*actual as i32-expected).abs()<=4,"limited-range luma sample {y}");}}
pipeline::export_high(&s.project,&path,format,0).unwrap();assert_eq!(before,decode(),"decoded deterministic repeat");std::fs::remove_file(path).unwrap();}}

#[test]fn inspector_and_rejection_precede_write(){let mut s=Session::new();let v=dispatch(&mut s,"inspect_high_bit_delivery_contract",&json!({"format":"hevc10"})).unwrap();assert_eq!(v["pipe_bits"],16);assert_eq!(v["output_bits"],10);assert_eq!(v["range"],"tv");dispatch(&mut s,"project_set",&json!({"width":32,"height":32})).unwrap();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","start":0,"duration":1})).unwrap();s.project.color_pipeline.enabled=true;s.project.color_pipeline.output_transfer=2;let path=format!("/tmp/rejected-highbit-{}.mp4",std::process::id());assert!(pipeline::export_high(&s.project,&path,"hevc10",20).is_err());assert!(!std::path::Path::new(&path).exists());}
#[test]fn managed_actual_tags(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":32,"fps":25})).unwrap();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","color":[0.25,0.5,0.75],"start":0,"duration":0.04})).unwrap();s.project.color_pipeline.enabled=true;for(g,tr)in [(0,0),(0,1),(0,8),(1,0),(1,1),(1,8),(1,6),(1,7)]{s.project.color_pipeline.output_gamut=g;s.project.color_pipeline.output_transfer=tr;for format in ["hevc10","ffv1_16"]{let c=encode_contract::high(&s.project.color_pipeline,format).unwrap();let path=format!("/tmp/managed-tags-{}-{}.{}",std::process::id(),format,if format=="hevc10"{"mp4"}else{"mkv"});pipeline::export_high(&s.project,&path,format,20).unwrap();let p=Command::new("ffprobe").args(["-v","error","-show_entries","stream=pix_fmt,color_range,color_space,color_transfer,color_primaries","-of","json",&path]).output().unwrap();let v:serde_json::Value=serde_json::from_slice(&p.stdout).unwrap();let st=&v["streams"][0];assert_eq!(st["color_primaries"],c.primaries);assert_eq!(st["color_transfer"],c.transfer_tag);assert_eq!(st["color_range"],c.range);assert_eq!(st["color_space"],if format=="hevc10"{c.matrix}else{"gbr"});assert_eq!(st["pix_fmt"],c.output_pixel_format);std::fs::remove_file(path).unwrap();}}}
#[test]fn matrix_swatch_709_and_2020(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":32,"fps":25})).unwrap();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","color":[0.18,0.42,0.73],"start":0,"duration":0.04})).unwrap();for managed in [false,true]{s.project.color_pipeline.enabled=managed;s.project.color_pipeline.output_gamut=1;s.project.color_pipeline.output_transfer=1;let mut cache=kimo_core::render::Cache::new();let mut f=kimo_core::render::render_frame(&s.project,0.,&mut cache).unwrap();pipeline::output(&s.project,&mut f).unwrap();let packed=pipeline::rgba16(&f).unwrap();let rgb:Vec<f64>=packed[..6].chunks_exact(2).map(|v|u16::from_le_bytes([v[0],v[1]]) as f64/65535.).collect();let weights=if managed{[0.2627,0.6780,0.0593]}else{[0.2126,0.7152,0.0722]};let expected=(64.+876.*rgb.iter().zip(weights).map(|(v,w)|v*w).sum::<f64>()).round() as i32;let path=format!("/tmp/matrix-swatch-{}.mp4",std::process::id());pipeline::export_high(&s.project,&path,"hevc10",0).unwrap();let b=Command::new("ffmpeg").args(["-v","error","-i",&path,"-frames:v","1","-f","rawvideo","-pix_fmt","yuv420p10le","-"]).output().unwrap().stdout;let actual=u16::from_le_bytes([b[0],b[1]]) as i32;assert!((actual-expected).abs()<=2,"matrix {managed}: {actual} vs {expected}");std::fs::remove_file(path).unwrap();}}
